CITIES=['Казань','Пермь','Тюмень','Уфа']
CATEGORIES=['кофе','не кофе','еда']
INT_RANGES={'tenure_months':(1,120),'app':(0,1),'visits_90d':(0,None),'days_since_last':(0,3650),'promo_used':(0,None),'complaints':(0,None)}
def is_int(x):
    return isinstance(x,int) and not isinstance(x,bool)
def is_number(x):
    return isinstance(x,(int,float)) and not isinstance(x,bool)
def validate_v1(p):
    errors=[]
    required=['city','fav_category','avg_check','delivery_share']+list(INT_RANGES)
    for f in required:
        if f not in p:
            errors.append(f'{f}: обязательное поле')
    if 'city' in p and p['city'] not in CITIES:
        errors.append('city: неизвестный город')
    if 'fav_category' in p and p['fav_category'] not in CATEGORIES:
        errors.append('fav_category: неизвестная категория')
    for f,(lo,hi) in INT_RANGES.items():
        if f not in p:
            continue
        if not is_int(p[f]):
            errors.append(f'{f}: ожидается целое число')
        elif p[f]<lo or (hi is not None and p[f]>hi):
            errors.append(f'{f}: вне диапазона')
    if 'avg_check' in p and p['avg_check'] is not None:
        v=p['avg_check']
        if not is_number(v) or not 50<=v<=3000:
            errors.append('avg_check: ожидается число50–3000 или null')
    if 'delivery_share' in p:
        v=p['delivery_share']
        if not is_number(v) or not 0<=v<=1:
            errors.append('delivery_share: ожидается доля0–1')
    return errors

